onClick:
(() => {
    if (!tabla_venta.selectedRows || tabla_venta.selectedRows.length === 0) {
        showAlert("No hay nada seleccionado", "warning");
    } else {
        Query_borrar.run().then(async () => {
            // Actualizamos el contador total de la paginación
            await Total_record_public_detalle_de_ventas1.run();

            // Ejecutamos el JS Object (que internamente ya trae los datos nuevos de la SQL y pinta los colores)
            await JSObject1.obtenerDatosConColor();

            showAlert("Registros borrados con éxito", "success");
        }).catch(() => {
            showAlert("Error al intentar borrar los registros", "error");
        });
    }
})();
